using System.Globalization;
using System.Text;
using BraunauMobil.VeloBasar.Data;
using Microsoft.EntityFrameworkCore;
using Xan.AspNetCore.EntityFrameworkCore;

namespace BraunauMobil.VeloBasar.BusinessLogic;

/// <summary>
/// Parses the QR payloads generated by the DataTransfer static site (see its README, "QR payload contract").
/// Format (schema version 3): <c>"VB" + schemaVersion + kind + body</c>, kind <c>S</c> = seller, <c>P</c> = product.
/// The body is base32hex (RFC 4648 §7, alphabet 0-9 A-V, no padding) of UTF-8(fields joined by TAB) followed by a
/// 2-byte big-endian CRC-16/CCITT-FALSE of those UTF-8 bytes.
/// The whole text is restricted to 0-9 A-V because keyboard-wedge barcode scanners "type" it through the host's
/// keyboard layout: on a scanner/host layout mismatch (US vs. German) Y/Z and all punctuation get swapped and
/// umlauts may not be typeable at all. Decoding is case-insensitive (Caps Lock), the CRC catches dropped characters.
/// Seller fields: firstName, lastName, street, city, zip, countryIso3, email, phoneNumber, iban, bankAccountHolder,
/// hasNewsletterPermission.
/// Product fields: brand, type, description, color, frameNumber, tireSize, price, donateIfNotSold.
/// </summary>
public sealed class QrImportService
    : IQrImportService
{
    private const string Marker = "VB";
    private const int SupportedSchemaVersion = 3;
    private const char SellerKindCode = 'S';
    private const char ProductKindCode = 'P';
    private const string SellerKindName = "seller";
    private const string ProductKindName = "product";
    private const int SellerFieldCount = 11;
    private const int ProductFieldCount = 8;
    private const char FieldSeparator = '\t';
    private const int CrcLength = 2;

    private static readonly UTF8Encoding _strictUtf8 = new(encoderShouldEmitUTF8Identifier: false, throwOnInvalidBytes: true);

    private readonly VeloDbContext _db;

    public QrImportService(VeloDbContext db)
    {
        _db = db ?? throw new ArgumentNullException(nameof(db));
    }

    public async Task<QrImportResult> TryApplyToSellerAsync(string? qrText, SellerEntity seller)
    {
        ArgumentNullException.ThrowIfNull(seller);

        QrImportResult? failure = TryReadPayload(qrText, SellerKindCode, SellerFieldCount, out string[] fields);
        if (failure is not null)
        {
            return failure;
        }

        seller.FirstName = fields[0];
        seller.LastName = fields[1];
        seller.Street = fields[2];
        seller.City = fields[3];
        seller.ZIP = fields[4];
        seller.EMail = NullIfEmpty(fields[6]);
        seller.PhoneNumber = fields[7];
        seller.IBAN = NullIfEmpty(fields[8]);
        seller.BankAccountHolder = NullIfEmpty(fields[9]);
        seller.HasNewsletterPermission = ParseBool(fields[10]);

        string countryIso3 = fields[5];
        string? unmatchedCountryIso3 = null;
        if (countryIso3.Length == 0)
        {
            seller.CountryId = 0;
        }
        else
        {
            List<CountryEntity> countries = await _db.Countries.WhereEnabled().ToListAsync();
            CountryEntity? country = countries.FirstOrDefault(c => string.Equals(c.Iso3166Alpha3Code, countryIso3, StringComparison.OrdinalIgnoreCase));
            if (country is null)
            {
                seller.CountryId = 0;
                unmatchedCountryIso3 = countryIso3;
            }
            else
            {
                seller.CountryId = country.Id;
            }
        }

        return QrImportResult.Success(unmatchedCountryIso3: unmatchedCountryIso3);
    }

    public async Task<QrImportResult> TryApplyToProductAsync(string? qrText, ProductEntity product)
    {
        ArgumentNullException.ThrowIfNull(product);

        QrImportResult? failure = TryReadPayload(qrText, ProductKindCode, ProductFieldCount, out string[] fields);
        if (failure is not null)
        {
            return failure;
        }

        product.Brand = fields[0];
        product.Description = fields[2];
        product.Color = NullIfEmpty(fields[3]);
        product.FrameNumber = NullIfEmpty(fields[4]);
        product.TireSize = NullIfEmpty(fields[5]);
        product.Price = ParseDecimal(fields[6]);
        product.DonateIfNotSold = ParseBool(fields[7]);

        string type = fields[1];
        string? unmatchedProductType = null;
        if (type.Length == 0)
        {
            product.TypeId = 0;
        }
        else
        {
            List<ProductTypeEntity> types = await _db.ProductTypes.WhereEnabled().ToListAsync();
            ProductTypeEntity? productType = types.FirstOrDefault(t => string.Equals(t.Name, type, StringComparison.OrdinalIgnoreCase));
            if (productType is null)
            {
                product.TypeId = 0;
                unmatchedProductType = type;
            }
            else
            {
                product.TypeId = productType.Id;
            }
        }

        return QrImportResult.Success(unmatchedProductType: unmatchedProductType);
    }

    private static QrImportResult? TryReadPayload(string? qrText, char expectedKindCode, int expectedFieldCount, out string[] fields)
    {
        fields = [];

        if (string.IsNullOrWhiteSpace(qrText))
        {
            return QrImportResult.Empty();
        }

        ReadOnlySpan<char> text = qrText.AsSpan().Trim();
        if (!text.StartsWith(Marker, StringComparison.OrdinalIgnoreCase))
        {
            return QrImportResult.InvalidFormat();
        }
        text = text[Marker.Length..];

        int versionLength = 0;
        while (versionLength < text.Length && char.IsAsciiDigit(text[versionLength]))
        {
            versionLength++;
        }
        if (versionLength == 0
            || !int.TryParse(text[..versionLength], NumberStyles.None, CultureInfo.InvariantCulture, out int schemaVersion))
        {
            return QrImportResult.InvalidFormat();
        }
        if (schemaVersion != SupportedSchemaVersion)
        {
            return QrImportResult.UnsupportedSchemaVersion();
        }
        text = text[versionLength..];

        if (text.IsEmpty)
        {
            return QrImportResult.InvalidFormat();
        }
        char kindCode = char.ToUpperInvariant(text[0]);
        string? kindName = kindCode switch
        {
            SellerKindCode => SellerKindName,
            ProductKindCode => ProductKindName,
            _ => null
        };
        if (kindName is null)
        {
            return QrImportResult.InvalidFormat();
        }
        if (kindCode != expectedKindCode)
        {
            return QrImportResult.WrongKind(kindName);
        }

        if (!TryDecodeBase32Hex(text[1..], out byte[] bytes) || bytes.Length < CrcLength)
        {
            return QrImportResult.InvalidFormat();
        }

        ReadOnlySpan<byte> data = bytes.AsSpan(0, bytes.Length - CrcLength);
        int expectedCrc = (bytes[^2] << 8) | bytes[^1];
        if (Crc16CcittFalse(data) != expectedCrc)
        {
            return QrImportResult.ChecksumMismatch();
        }

        string decoded;
        try
        {
            decoded = _strictUtf8.GetString(data);
        }
        catch (DecoderFallbackException)
        {
            return QrImportResult.InvalidFormat();
        }

        string[] split = decoded.Split(FieldSeparator);
        if (split.Length != expectedFieldCount)
        {
            return QrImportResult.InvalidFormat();
        }

        fields = split;
        return null;
    }

    /// <summary>
    /// RFC 4648 base32hex without padding, case-insensitive. Trailing bits that don't form a full byte are dropped.
    /// </summary>
    private static bool TryDecodeBase32Hex(ReadOnlySpan<char> text, out byte[] bytes)
    {
        List<byte> result = new(text.Length * 5 / 8);
        int buffer = 0;
        int bits = 0;
        foreach (char c in text)
        {
            int value = c switch
            {
                >= '0' and <= '9' => c - '0',
                >= 'A' and <= 'V' => c - 'A' + 10,
                >= 'a' and <= 'v' => c - 'a' + 10,
                _ => -1
            };
            if (value < 0)
            {
                bytes = [];
                return false;
            }

            buffer = (buffer << 5) | value;
            bits += 5;
            if (bits >= 8)
            {
                bits -= 8;
                result.Add((byte)(buffer >> bits));
                buffer &= (1 << bits) - 1;
            }
        }

        bytes = [.. result];
        return true;
    }

    /// <summary>
    /// CRC-16/CCITT-FALSE: poly 0x1021, init 0xFFFF, no reflection, no final XOR. Check value of "123456789" is 0x29B1.
    /// </summary>
    private static int Crc16CcittFalse(ReadOnlySpan<byte> data)
    {
        int crc = 0xFFFF;
        foreach (byte b in data)
        {
            crc ^= b << 8;
            for (int bit = 0; bit < 8; bit++)
            {
                if ((crc & 0x8000) != 0)
                {
                    crc = ((crc << 1) ^ 0x1021) & 0xFFFF;
                }
                else
                {
                    crc = (crc << 1) & 0xFFFF;
                }
            }
        }
        return crc;
    }

    private static string? NullIfEmpty(string value)
    {
        if (value.Length == 0)
        {
            return null;
        }
        return value;
    }

    private static bool ParseBool(string value)
        => string.Equals(value, "true", StringComparison.OrdinalIgnoreCase);

    private static decimal ParseDecimal(string value)
    {
        decimal.TryParse(value, NumberStyles.Number, CultureInfo.InvariantCulture, out decimal result);
        return result;
    }
}
